package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import java.util.*;
import static com.ruoyi.ai.agent.AgentJson.*;

/** Existing isolated schema only; deliberately inconsistent state is injected into new test runs. */
public class B3RepairTest extends TestCase {
    private A1TestFixture f;private ControlledWriteService service;
    protected void setUp()throws Exception{assertTrue(Boolean.getBoolean("a1.schema.prepared"));f=new A1TestFixture();service=new ControlledWriteService(new AgentStore(f.db),f.guard,f.workbooks,f.versions,f.tx.getTransactionManager());A1TestFixture.inject(service,"enabled",true);A1TestFixture.inject(f.runs,"controlled",service);A1TestFixture.inject(f.guard,"enabled",true);A1TestFixture.inject(f.runs,"timeoutMs",900000L);}
    private ObjectNode request(){long w=f.seed("{\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Orders\",\"rowCount\":20,\"columnCount\":10,\"cellData\":{}}}}");ObjectNode ws=f.runs.workspace(w,1),q=obj().put("requestId",UUID.randomUUID().toString()).put("workbookId",w).put("branchId",ws.path("branchId").asLong()).put("loadedRevision",ws.path("loadedRevision").asText()).put("expectedRevision",ws.path("revision").asText()).put("expectedDraftVersion",-1).put("expectedBranchVersion",0).put("activeSheetId","s").put("overwrite","empty-only").put("goal","write");q.set("writeScopes",parse("[{\"sheetId\":\"s\",\"range\":\"B2\"}]"));q.set("actions",parse("[{\"type\":\"setCell\",\"sheetId\":\"s\",\"range\":\"B2\",\"value\":11}]"));return q;}
    private JsonNode[] bad(){return new JsonNode[]{LongNode.valueOf(4294967298L),DoubleNode.valueOf(2.5),TextNode.valueOf("2"),NullNode.instance,IntNode.valueOf(1),BooleanNode.TRUE,parse("{}"),parse("[]")};}
    private void reject(Runnable r){try{r.run();fail("Invalid input accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    private ObjectNode claim(ObjectNode r){return service.claim(r.path("runId").asText(),1,obj().put("clientId","repair").put("fencingToken",r.path("fencingToken").asLong()));}
    private ObjectNode receipt(ObjectNode m){ObjectNode q=obj().put("transportVersion",2).put("callId",m.path("callId").asText()).put("claimToken",m.path("claimToken").asText()).put("argsHash",m.path("argsHash").asText()).put("fencingToken",m.path("fencingToken").asLong()).put("ok",true);ArrayNode a=arr();for(JsonNode cell:m.path("cells")){ObjectNode c=cell.deepCopy();c.remove("before");c.put("formula","");a.add(c);}q.set("cells",a);return q;}
    private String ledger(ObjectNode r){return f.db.queryForObject("select call_json from ai_agent_tool_call where run_id=?",String.class,r.path("runId").asText());}
    public void testEveryInvalidDeclaredTransportIsRejectedAtBothCreationEntrypoints(){for(JsonNode v:bad())for(boolean direct:new boolean[]{true,false}){ObjectNode q=request();q.set("transportVersion",v);reject(()->{if(direct)service.create(q,1);else f.runs.create(q,1);});assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_run where workbook_id=?",Integer.class,q.path("workbookId").asLong()).intValue());assertNull(f.status(q.path("workbookId").asLong()).get("workingState"));}}
    public void testEveryInvalidClaimTransportLeavesCallPending(){ObjectNode r=service.create(request(),1);String before=ledger(r);for(JsonNode v:bad()){ObjectNode q=obj().put("clientId","repair").put("fencingToken",r.path("fencingToken").asLong());q.set("transportVersion",v);reject(()->service.claim(r.path("runId").asText(),1,q));assertEquals(before,ledger(r));}}
    public void testEveryInvalidReceiptTransportCannotSave(){ObjectNode q=request(),r=service.create(q,1),m=claim(r);String before=ledger(r);for(JsonNode v:bad()){ObjectNode ack=receipt(m);ack.set("transportVersion",v);reject(()->service.receipt(r.path("runId").asText(),1,ack));assertEquals(before,ledger(r));assertNull(f.status(q.path("workbookId").asLong()).get("workingState"));}}
    public void testChatAndPlanTransportDoNotNarrowNumbers(){for(JsonNode v:bad()){ObjectNode q=obj();q.set("transportVersion",v);reject(()->WriteManifest.checkTransport(q));ObjectNode meta=obj();meta.set("controlledWriteTransport",v);reject(()->WriteManifest.checkChatTransport(parse("[{\"type\":\"setCell\"}]"),meta,true));}}
    public void testExactIntegerTwoRemainsCompatible(){for(JsonNode v:new JsonNode[]{IntNode.valueOf(2),LongNode.valueOf(2),new BigIntegerNode(java.math.BigInteger.valueOf(2))}){ObjectNode q=obj();q.set("transportVersion",v);WriteManifest.checkTransport(q);}WriteManifest.checkTransport(obj());}
    public void testPlanTransportIsExactAtEveryDeclaredLevel(){ObjectNode q=request();JsonNode snapshot=f.runs.workspace(q.path("workbookId").asLong(),1).path("snapshot");for(JsonNode v:bad())for(int level=0;level<3;level++){ObjectNode p=(ObjectNode)parse("{\"steps\":[{\"stepId\":\"W\",\"tool\":\"apply_actions\",\"dependsOn\":[],\"inputBindings\":{\"overwrite\":\"empty-only\",\"actions\":[{\"type\":\"setCell\",\"sheetId\":\"s\",\"range\":\"B2\",\"value\":11}]},\"verificationRules\":[{\"type\":\"tool_success\"}]},{\"stepId\":\"V\",\"tool\":\"verify_result\",\"dependsOn\":[\"W\"],\"inputBindings\":{\"write\":{\"$step\":\"W\"},\"sheetId\":\"s\",\"range\":\"B2\",\"kind\":\"non_empty\"},\"verificationRules\":[{\"type\":\"tool_success\"}]}],\"acceptanceCriteria\":[{\"type\":\"step_succeeded\",\"stepId\":\"W\"},{\"type\":\"step_succeeded\",\"stepId\":\"V\"}]}");ObjectNode target=level==0?p:level==1?(ObjectNode)p.path("steps").get(0):(ObjectNode)p.path("steps").get(0).path("inputBindings");target.set("transportVersion",v);reject(()->AgentPlan.validateForRun(p,snapshot,q.path("writeScopes"),"s",false,true));}}
    private ObjectNode[] inconsistent(){ObjectNode q=request(),r=service.create(q,1),m=claim(r),ack=receipt(m);ObjectNode stale=(ObjectNode)new AgentStore(f.db).get(r.path("runId").asText()).path("call").deepCopy();service.receipt(r.path("runId").asText(),1,ack);f.tx.execute(tx->{AgentStore s=new AgentStore(f.db);ObjectNode current=s.locked(r.path("runId").asText());current.set("call",stale);current.remove("lastControlledResult");current.put("status","EXECUTING").put("persistenceStatus","NOT_SAVED");s.save(current);return null;});f.db.update("update ai_agent_lease set run_id=?,expires_at=? where workbook_id=?",r.path("runId").asText(),System.currentTimeMillis()+120000,q.path("workbookId").asLong());return new ObjectNode[]{q,r,m,ack};}
    private ObjectNode stop(ObjectNode r){f.runs.cancel(r.path("runId").asText(),1);ObjectNode ws=f.runs.workspace(r.path("workbookId").asLong(),1);return f.runs.resume(r.path("runId").asText(),1,obj().put("reloadedServerDraft",true).put("expectedRevision",ws.path("revision").asText()));}
    public void testSavedLedgerSurvivesStaleRunCancelAndResume(){ObjectNode[] a=inconsistent();String before=ledger(a[1]);ObjectNode ended=stop(a[1]);assertEquals("CANCELLED",ended.path("status").asText());assertEquals(before,ledger(a[1]));assertEquals("SAVED",ended.path("lastControlledResult").path("persistenceStatus").asText());service.receipt(a[1].path("runId").asText(),1,a[3]);assertEquals(before,ledger(a[1]));assertEquals(0,((Number)((Map<?,?>)f.status(a[0].path("workbookId").asLong()).get("workingState")).get("version")).intValue());reject(()->claim(a[1]));}
    public void testSavedLedgerSurvivesExpiredLeaseAndFenceAdvance(){ObjectNode[] a=inconsistent();long w=a[0].path("workbookId").asLong();f.db.update("update ai_agent_lease set expires_at=1,fencing_token=fencing_token+20 where workbook_id=?",w);long beforeFence=f.db.queryForObject("select fencing_token from ai_agent_lease where workbook_id=?",Long.class,w);String before=ledger(a[1]);stop(a[1]);assertTrue(f.db.queryForObject("select fencing_token from ai_agent_lease where workbook_id=?",Long.class,w)>beforeFence);assertEquals(before,ledger(a[1]));service.receipt(a[1].path("runId").asText(),1,a[3]);assertEquals(before,ledger(a[1]));}
    public void testLeaseTransferredToAnotherRunIsNotTakenBack(){ObjectNode[] a=inconsistent();long w=a[0].path("workbookId").asLong();String other=UUID.randomUUID().toString(),before=ledger(a[1]);f.db.update("update ai_agent_lease set run_id=?,fencing_token=40 where workbook_id=?",other,w);reject(()->stop(a[1]));assertEquals(other,f.db.queryForObject("select run_id from ai_agent_lease where workbook_id=?",String.class,w));assertEquals(40,f.db.queryForObject("select fencing_token from ai_agent_lease where workbook_id=?",Long.class,w).intValue());assertEquals(before,ledger(a[1]));}
    public void testMissingLedgerNeverFabricatesSavedFactAndKeepsControlledTaskProtected(){for(boolean modern:new boolean[]{true,false}){ObjectNode q=request(),r=f.runs.create(q,1);String id=r.path("runId").asText();f.tx.execute(tx->{AgentStore s=new AgentStore(f.db);ObjectNode state=s.locked(id),call=obj().put("callId","missing-record").put("status","UNKNOWN");if(modern)call.put("transportVersion",2);state.set("call",call);state.put("status","PAUSED");s.save(state);return null;});if(modern){reject(()->stop(r));assertTrue(f.runs.get(id,1).has("call"));assertEquals(1,f.db.queryForObject("select count(*) from ai_agent_lease where run_id=?",Integer.class,id).intValue());}else{ObjectNode ended=stop(r);assertEquals("CANCELLED",ended.path("status").asText());assertEquals("UNKNOWN",ended.path("unresolvedLegacyCall").path("status").asText());}assertEquals(0,f.db.queryForObject("select count(*) from ai_agent_tool_call where run_id=?",Integer.class,id).intValue());assertNull(f.status(q.path("workbookId").asLong()).get("workingState"));}}
}
